export interface MemberRecord {
  id: string;
  contact: string;
  tier: string;
}

export interface MemberQuery {
  contactText: string;
  page: number;
  pageSize: number;
}

export interface MemberPage {
  items: MemberRecord[];
  total: number;
  totalPages: number;
  page: number;
  pageSize: number;
}

export function queryMembers(
  records: readonly MemberRecord[],
  query: MemberQuery,
): MemberPage {
  if (!Array.isArray(records)) throw new TypeError("records must be an array");
  if (typeof query !== "object" || query === null) throw new TypeError("query must be an object");
  if (typeof query.contactText !== "string") throw new TypeError("contactText must be a string");
  if (!Number.isSafeInteger(query.page) || query.page < 1) throw new RangeError("page must be positive");
  if (!Number.isSafeInteger(query.pageSize) || query.pageSize < 1) throw new RangeError("pageSize must be positive");

  for (const record of records) {
    if (typeof record !== "object" || record === null ||
        typeof record.id !== "string" || typeof record.contact !== "string" ||
        typeof record.tier !== "string") {
      throw new TypeError("malformed member record");
    }
  }

  const needle = query.contactText.trim().toLowerCase();
  const matches = records.filter((record) => record.contact.toLowerCase().includes(needle));
  const start = query.page * query.pageSize;
  const items = matches.slice(start, start + query.pageSize).map((record) => ({ ...record }));
  return {
    items,
    total: matches.length,
    totalPages: matches.length === 0 ? 0 : Math.ceil(matches.length / query.pageSize),
    page: query.page,
    pageSize: query.pageSize,
  };
}

