import { queryMembers } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throws(action: () => void, kind: Function, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof (kind as any), message);
}

const records = [
  { id: '1', contact: 'Alice@example.com', tier: 'gold' },
  { id: '2', contact: 'bob@example.com', tier: 'silver' },
  { id: '3', contact: 'ALICIA@example.net', tier: 'bronze' },
  { id: '4', contact: 'malice@test.dev', tier: 'gold' },
];
const page = queryMembers(records, { contactText: '  ALI  ', page: 1, pageSize: 2 });
equal(page.items, [records[0], records[2]], 'case-insensitive ordered first page');
assert(page.total === 3 && page.totalPages === 2, 'totals');
assert(page.items !== records && page.items[0] !== records[0], 'records cloned');
page.items[0].contact = 'changed';
assert(records[0].contact === 'Alice@example.com', 'result cannot mutate input');

const second = queryMembers(records, { contactText: 'ali', page: 2, pageSize: 2 });
equal(second.items, [records[3]], 'second page');
const past = queryMembers(records, { contactText: '', page: 99, pageSize: 2 });
equal(past.items, [], 'page past end');
assert(past.total === 4 && past.totalPages === 2, 'past page totals');
const none = queryMembers(records, { contactText: 'missing', page: 1, pageSize: 3 });
assert(none.total === 0 && none.totalPages === 0 && none.items.length === 0, 'no matches');

throws(() => queryMembers(null as any, { contactText: '', page: 1, pageSize: 1 }), TypeError, 'records array required');
throws(() => queryMembers([{ id: '1', contact: 2, tier: 'x' } as any], { contactText: '', page: 1, pageSize: 1 }), TypeError, 'malformed record rejected');
throws(() => queryMembers(records, { contactText: 4 as any, page: 1, pageSize: 1 }), TypeError, 'search text type');
for (const value of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  throws(() => queryMembers(records, { contactText: '', page: value, pageSize: 1 }), RangeError, 'invalid page');
  throws(() => queryMembers(records, { contactText: '', page: 1, pageSize: value }), RangeError, 'invalid page size');
}

